
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_baltin_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_baltin", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.047766664917397e+02, 1.011019397502221e+02, 9.607537388520626e+01, 8.934895701376929e+01, 8.062627654431630e+01, 6.981052824324857e+01, 5.722414254418528e+01, 4.381886276726355e+01, 3.112590598311752e+01, 2.040692296792663e+01, 1.046466101514319e+01, 3.020745910514444e+00, 2.044089504428556e+00, 1.527259750007622e+00, 9.767610666146218e-01, 6.026574791453021e-01, 4.305868335742089e-01, 3.643516640729779e-01, 3.354676264437755e-01, 3.190852738022679e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


